import gleam/float
import gleam/int
import gleam/io
import gleam/list
import gleam/result

pub type Matrix {
  Matrix(rows: Int, cols: Int, data: List(Float))
}

pub fn random(rows: Int, cols: Int) -> Matrix {
  let size = rows * cols
  let data = generate_random_floats(size, [])
  Matrix(rows: rows, cols: cols, data: data)
}

fn generate_random_floats(count: Int, acc: List(Float)) -> List(Float) {
  case count {
    0 -> list.reverse(acc)
    _ -> {
      let value = float.random()
      generate_random_floats(count - 1, [value, ..acc])
    }
  }
}

pub fn scale(matrix: Matrix, factor: Float) -> Matrix {
  let scaled_data = list.map(matrix.data, fn(x) { x *. factor })
  Matrix(rows: matrix.rows, cols: matrix.cols, data: scaled_data)
}

pub fn initialize_embeddings(vocab_size: Int, dim: Int) -> Matrix {
  let sqrt_dim = float.square_root(int.to_float(dim)) |> result.unwrap(1.0)
  let scale_factor = 1.0 /. sqrt_dim
  random(vocab_size, dim)
  |> scale(scale_factor)
}

pub fn orthogonal_init(dim: Int) -> Matrix {
  random(dim, dim)
}

pub fn main() {
  let _embeds = initialize_embeddings(100, 9216)
  io.println("Embeddings initialized")
  Nil
}
